/**
 * The animation presets (`animations.css`), by group. `enter` presets arrive, `attention` presets play once to draw the
 * eye, `loop` presets repeat until stopped, `exit` presets leave and stay gone. Names are the values of
 * `data-hm-anim`.
 */
export const animations = {
  enter: [
    "fade-in",
    "fade-up",
    "fade-down",
    "fade-left",
    "fade-right",
    "slide-up",
    "slide-down",
    "slide-left",
    "slide-right",
    "zoom-in",
    "zoom-out",
    "pop",
    "blur-in",
    "flip-x",
    "flip-y",
    "rotate-in",
    "swing-in",
    "drop",
    "unfold",
    "expand",
    "wipe-up",
    "wipe-down",
    "curtain",
    "spring-up",
    "tilt-in",
    "skew-in",
    "letter-in",
  ] as const,
  attention: [
    "pulse",
    "heartbeat",
    "shake",
    "wiggle",
    "bounce",
    "jello",
    "rubber",
    "tada",
    "flash",
    "swing",
    "ping",
    "blink",
    "flip-once",
    "hop",
    "nudge-right",
    "nudge-left",
    "nudge-up",
    "nudge-down",
    "spin-once",
  ] as const,
  loop: ["float", "breathe", "glow-pulse", "spin", "orbit", "sway", "shimmer-slide", "wave-y", "rise-fall"] as const,
  exit: [
    "fade-out",
    "fade-out-up",
    "fade-out-down",
    "zoom-exit",
    "shrink",
    "blur-out",
    "fall",
    "slide-out-left",
    "slide-out-right",
  ] as const,
};

export type EnterAnimation = (typeof animations.enter)[number];
export type AttentionAnimation = (typeof animations.attention)[number];
export type LoopAnimation = (typeof animations.loop)[number];
export type ExitAnimation = (typeof animations.exit)[number];
export type AnimationName = EnterAnimation | AttentionAnimation | LoopAnimation | ExitAnimation;

/** When a preset plays. `mount` is the default; `view` waits until the element scrolls into view. */
export type AnimationTrigger = "mount" | "view" | "hover" | "focus" | "click" | "manual" | "group";

export type AnimationOptions = {
  /** Milliseconds, or any CSS time. Each preset has its own default. */
  duration?: number | string;
  /** Milliseconds, or any CSS time. */
  delay?: number | string;
  /** A CSS easing, such as `var(--hm-ease-spring)`. */
  easing?: string;
  /** Number of plays, or `infinite`. */
  count?: number | "infinite";
  direction?: "normal" | "reverse" | "alternate" | "alternate-reverse";
  /** How far fade and slide presets travel, as a CSS length. */
  distance?: string;
  /** Milliseconds between staggered items (`--hm-i`). */
  step?: number | string;
};

const time = (v: number | string | undefined) => (v === undefined ? undefined : typeof v === "number" ? `${v}ms` : v);

/** The custom properties for a set of options, as a style object. Server-safe. */
export function animationVars(o: AnimationOptions = {}): Record<string, string> {
  const vars: Record<string, string | undefined> = {
    "--hm-anim-duration": time(o.duration),
    "--hm-anim-delay": time(o.delay),
    "--hm-anim-easing": o.easing,
    "--hm-anim-count": o.count === undefined ? undefined : String(o.count),
    "--hm-anim-direction": o.direction,
    "--hm-anim-distance": o.distance,
    "--hm-anim-step": time(o.step),
  };
  const out: Record<string, string> = {};
  for (const k of Object.keys(vars)) {
    const v = vars[k];
    if (v !== undefined) out[k] = v;
  }
  return out;
}

/**
 * Props to spread on any element (server or client) to play a preset:
 * `<h1 {...animationAttrs("fade-up", { delay: 120 })}>`. Pass `index` to stagger a list.
 */
export function animationAttrs(
  name: AnimationName,
  options: AnimationOptions & { trigger?: AnimationTrigger; index?: number } = {},
) {
  const { trigger, index, ...rest } = options;
  const style: Record<string, string> = animationVars(rest);
  if (index !== undefined) style["--hm-i"] = String(index);
  return {
    "data-hm-anim": name,
    "data-hm-trigger": trigger && trigger !== "mount" ? trigger : undefined,
    style: style as import("react").CSSProperties,
  };
}

const reduced = (el: Element) => {
  const forced = el.closest("[data-hm-motion]")?.getAttribute("data-hm-motion");
  if (forced === "reduce") return true;
  if (forced === "full") return false;
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
};

/**
 * Plays a preset on an element now and resolves when it ends: `await animate(input, "shake")`. Replays if called again.
 * Entrance and attention presets clear themselves afterwards so the element rests normally; exit presets stay applied
 * (pass `keep: false` to clear them too). Resolves at once under reduced motion. Browser-only.
 */
export function animate(
  el: HTMLElement,
  name: AnimationName,
  options: AnimationOptions & { keep?: boolean } = {},
): Promise<void> {
  const { keep, ...rest } = options;
  const isExit = (animations.exit as readonly string[]).includes(name);
  const vars = animationVars(rest);
  for (const [k, v] of Object.entries(vars)) el.style.setProperty(k, v);
  el.setAttribute("data-hm-anim", name);
  el.setAttribute("data-hm-trigger", "manual");
  el.removeAttribute("data-hm-play");
  el.removeAttribute("data-hm-pending");
  if (reduced(el)) return Promise.resolve();
  void el.offsetWidth; // restart: the preset is off for a frame, then on
  el.setAttribute("data-hm-play", "");
  const clear = () => {
    if (isExit && keep !== false) return;
    el.removeAttribute("data-hm-play");
    el.removeAttribute("data-hm-anim");
    el.removeAttribute("data-hm-trigger");
    for (const k of Object.keys(vars)) el.style.removeProperty(k);
  };
  return new Promise((resolve) => {
    const anims = el.getAnimations().filter((a) => (a as CSSAnimation).animationName?.startsWith("hm-a-"));
    if (anims.length === 0) {
      clear();
      resolve();
      return;
    }
    Promise.all(anims.map((a) => a.finished.catch(() => undefined))).then(() => {
      clear();
      resolve();
    });
  });
}
